   if(f.action==="MINE"&&(f.boardKind!=="BLOCK"||f.type!=="ORE"||!["CHOSEN_FRIENDLY","RANDOM_FRIENDLY_MOB"].includes(f.target)||!["PLAY","AFTER_ATTACK"].includes(f.trigger)))fail(id,"Mine requires a friendly Ore block on Play or After attack","target");
