function wordingAdvice(c,catalog) {
 const advice=[],text=description(c,catalog),effects=c.effects||[];
 if(!c.autoText)advice.push("Custom wording does not change effects. Check it against the structured rules, or enable Automatic description.");
 if(text.trim().split(/\s+/).length>40)advice.push("Over 40 rules words: consider one main effect or shorter phrasing before reducing the font size.");
 if(["ITEM","ENCHANTMENT"].includes(c.kind)&&/\bPlay:/i.test(text))advice.push("The Play: prefix is usually unnecessary on an Action or Enchantment.");
 if(effects.some(f=>f.trigger==="DISMANTLE"))advice.push("Dismantle is retired. This effect will not fire; redesign the block's payoff.");
 if(c.keywords.includes("BLOCK")&&c.passive==="NONE"&&!effects.some(f=>!["PLAY","DROP","DISMANTLE"].includes(f.trigger))&&!["ORE","CROP"].includes(c.type))advice.push("This block has no ongoing effect or Mine/Harvest payoff. Give it a reason to keep occupying a board slot.");
 if(effects.some(f=>OBSERVED.includes(f.trigger)&&f.trigger!=="HEALED"&&f.eventScope==="SELF"))advice.push("Self is not a useful scope for this observed event. Choose Friendly, Enemy or Any as appropriate.");
 if(!c.autoText&&/once per turn/i.test(text)&&c.passive!=="BATTLE_HARDENED")advice.push("Writing once per turn does not enforce a limit. Check that the intended mechanic actually supports the cap.");
 return advice;
}
